from fastapi import FastAPI, Depends

app = FastAPI()

def dep_a():
    return "A"

def dep_b(a: str = Depends(dep_a)):
    return f"B-{a}"

@app.get("/")
async def main(b: str = Depends(dep_b)):
    return b

from fastapi import FastAPI, Query

app = FastAPI()

@app.get("/")
async def read_items(skip: int = Query(0), limit: int = Query(10)):
    return {"skip": skip, "limit": limit}

from fastapi import FastAPI, HTTPException

app = FastAPI()

@app.get("/items/{item_id}")
async def get_item(item_id: int):
    if item_id == 0:
        raise HTTPException(status_code=404, detail="Item not found")
    return {"item_id": item_id}

from fastapi import FastAPI, Query

app = FastAPI()

def get_name(name: str = Query(...)):
    return name

@app.get("/test")
async def test(name: str = Depends(get_name)):
    return {"name": name}

from fastapi import FastAPI, BackgroundTasks

app = FastAPI()

def log_msg(msg: str):
    with open("log.txt", "a") as f:
        f.write(f"{msg}\n")

@app.post("/log")
async def log(background_tasks: BackgroundTasks, msg: str):
    background_tasks.add_task(log_msg, msg)
    return {"status": "logged"}
